 1→/**
 2→ * Vault key blob operations
 3→ *
 4→ * The vault key blob stores the ECIES-wrapped rootFolderKey on IPFS,
 5→ * published to a dedicated IPNS name derived via HKDF. This separates
 6→ * key storage from folder metadata so folder updates don't overwrite the key.
 7→ *
 8→ * - publishVaultKeyBlob: wraps rootFolderKey and publishes to IPNS (called during vault init)
 9→ * - loadVaultKeyBlob: resolves IPNS, fetches blob, unwraps rootFolderKey (called on login)
10→ */
11→
12→import { deriveVaultKeyIpnsKeypair, wrapKey, unwrapKey } from '@cipherbox/crypto';
13→import { serializeVaultBlobV2, deserializeVaultBlobV2, detectBlobVersion } from '@cipherbox/core';
14→import type { SdkContext } from '../types';
15→import { addToIpfs, fetchFromIpfs } from '../ipfs';
16→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../ipns';
17→
18→/**
19→ * Publish the vault key blob to IPNS.
20→ *
21→ * Wraps rootFolderKey with the user's publicKey via ECIES, serializes as a v2 blob,
22→ * uploads to IPFS, and publishes the CID to the vault key IPNS name.
23→ *
24→ * @returns The vault key IPNS name
25→ */
26→export async function publishVaultKeyBlob(params: {
27→  userPrivateKey: Uint8Array;
28→  userPublicKey: Uint8Array;
29→  rootFolderKey: Uint8Array;
30→  ctx: SdkContext;
31→}): Promise<{ ipnsName: string }> {
32→  const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(params.userPrivateKey);
33→
34→  const encryptedRootFolderKey = await wrapKey(params.rootFolderKey, params.userPublicKey);
35→  const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey);
36→
37→  const { cid } = await addToIpfs(params.ctx, new Uint8Array(v2Blob));
38→  const result = await createAndPublishIpnsRecord({
39→    ipnsPrivateKey: vaultKeyKeypair.privateKey,
40→    ipnsName: vaultKeyKeypair.ipnsName,
41→    metadataCid: cid,
42→    sequenceNumber: 0n,
43→    ctx: params.ctx,
44→  });
45→
46→  if (!result.success) {
47→    throw new Error('Failed to publish vault key blob to IPNS');
48→  }
49→
50→  return { ipnsName: vaultKeyKeypair.ipnsName };
51→}
52→
53→/**
54→ * Load the vault key blob from IPNS and decrypt the rootFolderKey.
55→ *
56→ * Resolves the vault key IPNS name, fetches the v2 blob from IPFS,
57→ * and unwraps the rootFolderKey using the user's privateKey.
58→ *
59→ * @returns The decrypted rootFolderKey, or null if the IPNS record doesn't exist
60→ */
61→export async function loadVaultKeyBlob(params: {
62→  userPrivateKey: Uint8Array;
63→  ctx: SdkContext;
64→}): Promise<{ rootFolderKey: Uint8Array; ipnsName: string } | null> {
65→  const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(params.userPrivateKey);
66→
67→  const resolved = await resolveIpnsRecord(vaultKeyKeypair.ipnsName, params.ctx);
68→  if (!resolved) return null;
69→
70→  const blobBytes = await fetchFromIpfs(params.ctx, resolved.cid);
71→
72→  if (detectBlobVersion(blobBytes) !== 2) {
73→    throw new Error('Vault key blob is not v2 format');
74→  }
75→
76→  const encryptedKey = deserializeVaultBlobV2(blobBytes);
77→  const rootFolderKey = await unwrapKey(encryptedKey, params.userPrivateKey);
78→
79→  return { rootFolderKey, ipnsName: vaultKeyKeypair.ipnsName };
80→}
