231→/**
232→ * Rename a child entry (folder or file) in folder metadata.
233→ *
234→ * Pure metadata operation: returns updated children array without publishing.
235→ */
236→export function renameInFolder(params: {
237→  children: FolderChild[];
238→  childId: string;
239→  newName: string;
240→}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
241→  const children = [...params.children];
242→  const index = children.findIndex((c) => c.id === params.childId);
243→
244→  if (index === -1) throw new Error('Item not found');
245→
246→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.childId);
247→  if (nameExists) throw new Error('An item with this name already exists');
248→
249→  const renamedChild = {
250→    ...children[index],
251→    name: params.newName,
252→    modifiedAt: Date.now(),
253→  };
254→  children[index] = renamedChild;
255→
256→  return { updatedChildren: children, renamedChild };
257→}
