existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();

// SDK: Track current sequence, increment before publish (packages/sdk-core/src/folder/index.ts:197-206)
const newSeq = currentSeq + 1n;
await createAndPublishIpnsRecord({
  sequenceNumber: newSeq,
  expectedSequenceNumber: currentSeq.toString(), // Pre-increment for conflict detection
  ...
});
```

