  1→/**
  2→ * @cipherbox/crypto - Vault IPNS Key Derivation
  3→ *
  4→ * Derives a deterministic Ed25519 IPNS keypair for the user's vault
  5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
  6→ *
  7→ * Derivation path:
  8→ *   secp256k1 privateKey (32 bytes)
  9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-vault-ipns-v1")
 10→ *     -> 32-byte Ed25519 seed
 11→ *     -> Ed25519 keypair
 12→ *     -> IPNS name (k51...)
 13→ *
 14→ * This enables self-sovereign vault recovery: recovery phrase -> privateKey
 15→ * -> derive vault IPNS key -> resolve IPNS -> decrypt vault.
 16→ *
 17→ * Domain separation: Uses "cipherbox-vault-ipns-v1" info (different from
 18→ * registry's "cipherbox-device-registry-ipns-v1"), ensuring the same
 19→ * privateKey produces different IPNS keypairs for vault vs registry.
 20→ */
 21→
 22→import { deriveKey } from '../keys/derive';
 23→import * as ed from '@noble/ed25519';
 24→import { deriveIpnsName } from '../ipns/derive-name';
 25→import { CryptoError } from '../types';
 26→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
 27→
 28→const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
 29→const VAULT_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
 30→const VAULT_KEY_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-key-ipns-v1');
 31→const BYO_CONFIG_HKDF_INFO = new TextEncoder().encode('cipherbox-byo-ipfs-config-v1');
 32→
 33→/**
 34→ * Derive the deterministic Ed25519 IPNS keypair for the user's vault.
 35→ *
 36→ * Given the same secp256k1 privateKey, this always produces the same
 37→ * IPNS name, enabling vault discovery from any device with the user's key.
 38→ *
 39→ * @param userPrivateKey - 32-byte secp256k1 private key
 40→ * @returns Ed25519 keypair and IPNS name for the vault
 41→ * @throws CryptoError if the private key is not 32 bytes
 42→ */
 43→export async function deriveVaultIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
 44→  privateKey: Uint8Array;
 45→  publicKey: Uint8Array;
 46→  ipnsName: string;
 47→}> {
 48→  // Validate input key length
 49→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
 50→    throw new CryptoError('Invalid private key size for vault derivation', 'INVALID_KEY_SIZE');
 51→  }
 52→
 53→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
 54→  const ed25519Seed = await deriveKey({
 55→    inputKey: userPrivateKey,
 56→    salt: VAULT_HKDF_SALT,
 57→    info: VAULT_HKDF_INFO,
 58→    outputLength: 32,
 59→  });
 60→
 61→  // 2. Derive Ed25519 public key from seed (deterministic)
 62→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
 63→
 64→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
 65→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
 66→
 67→  return {
 68→    privateKey: ed25519Seed,
 69→    publicKey: ed25519PublicKey,
 70→    ipnsName,
 71→  };
 72→}
 73→
 74→/**
 75→ * Derive a dedicated Ed25519 IPNS keypair for the vault key blob.
 76→ *
 77→ * This IPNS name stores the v2 blob containing the ECIES-wrapped rootFolderKey.
 78→ * It is separate from the root folder IPNS name (which stores standard v1 folder
 79→ * metadata) to avoid folder publishes overwriting the key blob.
 80→ *
 81→ * Uses "cipherbox-vault-key-ipns-v1" info for domain separation from the root
 82→ * folder's "cipherbox-vault-ipns-v1".
 83→ *
 84→ * @param userPrivateKey - 32-byte secp256k1 private key
 85→ * @returns Ed25519 keypair and IPNS name for the vault key blob
 86→ * @throws CryptoError if the private key is not 32 bytes
 87→ */
 88→export async function deriveVaultKeyIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
 89→  privateKey: Uint8Array;
 90→  publicKey: Uint8Array;
 91→  ipnsName: string;
