  1→/**
  2→ * @cipherbox/crypto - Vault IPNS Key Derivation
  3→ *
  4→ * Derives a deterministic Ed25519 IPNS keypair for the user's vault
  5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
  6→ *
  7→ * Derivation path:
  8→ *   secp256k1 privateKey (32 bytes)
  9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-vault-ipns-v1")
 10→ *     -> 32-byte Ed25519 seed
 11→ *     -> Ed25519 keypair
 12→ *     -> IPNS name (k51...)
 13→ *
 14→ * This enables self-sovereign vault recovery: recovery phrase -> privateKey
 15→ * -> derive vault IPNS key -> resolve IPNS -> decrypt vault.
 16→ *
 17→ * Domain separation: Uses "cipherbox-vault-ipns-v1" info (different from
 18→ * registry's "cipherbox-device-registry-ipns-v1"), ensuring the same
 19→ * privateKey produces different IPNS keypairs for vault vs registry.
 20→ */
 21→
 22→import { deriveKey } from '../keys/derive';
 23→import * as ed from '@noble/ed25519';
 24→import { deriveIpnsName } from '../ipns/derive-name';
 25→import { CryptoError } from '../types';
 26→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
 27→
 28→const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
 29→const VAULT_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
 30→const VAULT_KEY_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-key-ipns-v1');
 31→const BYO_CONFIG_HKDF_INFO = new TextEncoder().encode('cipherbox-byo-ipfs-config-v1');
 32→
 33→/**
 34→ * Derive the deterministic Ed25519 IPNS keypair for the user's vault.
 35→ *
 36→ * Given the same secp256k1 privateKey, this always produces the same
 37→ * IPNS name, enabling vault discovery from any device with the user's key.
 38→ *
 39→ * @param userPrivateKey - 32-byte secp256k1 private key
 40→ * @returns Ed25519 keypair and IPNS name for the vault
 41→ * @throws CryptoError if the private key is not 32 bytes
 42→ */
 43→export async function deriveVaultIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
 44→  privateKey: Uint8Array;
 45→  publicKey: Uint8Array;
 46→  ipnsName: string;
 47→}> {
 48→  // Validate input key length
 49→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
 50→    throw new CryptoError('Invalid private key size for vault derivation', 'INVALID_KEY_SIZE');
 51→  }
 52→
 53→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
 54→  const ed25519Seed = await deriveKey({
 55→    inputKey: userPrivateKey,
 56→    salt: VAULT_HKDF_SALT,
 57→    info: VAULT_HKDF_INFO,
 58→    outputLength: 32,
 59→  });
 60→
 61→  // 2. Derive Ed25519 public key from seed (deterministic)
 62→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
 63→
 64→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
 65→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
 66→
 67→  return {
 68→    privateKey: ed25519Seed,
 69→    publicKey: ed25519PublicKey,
 70→    ipnsName,
 71→  };
 72→}
 73→
 74→/**
 75→ * Derive a dedicated Ed25519 IPNS keypair for the vault key blob.
 76→ *
 77→ * This IPNS name stores the v2 blob containing the ECIES-wrapped rootFolderKey.
 78→ * It is separate from the root folder IPNS name (which stores standard v1 folder
 79→ * metadata) to avoid folder publishes overwriting the key blob.
 80→ *
 81→ * Uses "cipherbox-vault-key-ipns-v1" info for domain separation from the root
 82→ * folder's "cipherbox-vault-ipns-v1".
 83→ *
 84→ * @param userPrivateKey - 32-byte secp256k1 private key
 85→ * @returns Ed25519 keypair and IPNS name for the vault key blob
 86→ * @throws CryptoError if the private key is not 32 bytes
 87→ */
 88→export async function deriveVaultKeyIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
 89→  privateKey: Uint8Array;
 90→  publicKey: Uint8Array;
 91→  ipnsName: string;
 92→}> {
 93→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
 94→    throw new CryptoError('Invalid private key size for vault key derivation', 'INVALID_KEY_SIZE');
 95→  }
 96→
 97→  const ed25519Seed = await deriveKey({
 98→    inputKey: userPrivateKey,
 99→    salt: VAULT_HKDF_SALT,
100→    info: VAULT_KEY_HKDF_INFO,
101→    outputLength: 32,
102→  });
103→
104→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
105→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
106→
107→  return {
108→    privateKey: ed25519Seed,
109→    publicKey: ed25519PublicKey,
110→    ipnsName,
111→  };
112→}
113→
114→/**
115→ * Derive a dedicated Ed25519 IPNS keypair for BYO-IPFS config storage.
116→ *
117→ * This IPNS name stores the encrypted BYO-IPFS configuration (pinning mode,
118→ * external node endpoint, auth token). Zero-knowledge: the server never sees
119→ * the plaintext config.
120→ *
121→ * Uses "cipherbox-byo-ipfs-config-v1" info for domain separation.
122→ *
123→ * @param userPrivateKey - 32-byte secp256k1 private key
124→ * @returns Ed25519 keypair and IPNS name for the BYO config
125→ * @throws CryptoError if the private key is not 32 bytes
126→ */
127→export async function deriveByoConfigIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
128→  privateKey: Uint8Array;
129→  publicKey: Uint8Array;
130→  ipnsName: string;
131→}> {
132→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
133→    throw new CryptoError('Invalid private key size for BYO config derivation', 'INVALID_KEY_SIZE');
134→  }
135→
136→  const ed25519Seed = await deriveKey({
137→    inputKey: userPrivateKey,
138→    salt: VAULT_HKDF_SALT,
139→    info: BYO_CONFIG_HKDF_INFO,
140→    outputLength: 32,
141→  });
142→
143→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
144→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
145→
146→  return {
147→    privateKey: ed25519Seed,
148→    publicKey: ed25519PublicKey,
149→    ipnsName,
150→  };
151→}
152→

 1→/**
 2→ * @cipherbox/crypto - ECIES Key Wrapping (Encryption)
 3→ *
 4→ * Wraps symmetric keys using ECIES with secp256k1.
 5→ * Uses eciesjs library which handles ephemeral keys, ECDH, HKDF, and AES-GCM internally.
 6→ */
 7→
 8→import { encrypt } from 'eciesjs';
 9→import { ProjectivePoint } from '@noble/secp256k1';
10→import { CryptoError } from '../types';
11→import { SECP256K1_PUBLIC_KEY_SIZE } from '../constants';
12→
13→/**
14→ * Wrap a key using ECIES encryption.
15→ *
16→ * Encrypts a symmetric key (or any data) to a recipient's public key.
17→ * Only the holder of the corresponding private key can unwrap it.
18→ *
19→ * Each call produces different ciphertext due to ephemeral key generation.
20→ *
21→ * @param key - Data to wrap (typically a 32-byte file key)
22→ * @param recipientPublicKey - 65-byte uncompressed secp256k1 public key
23→ * @returns Wrapped key ciphertext
24→ * @throws CryptoError with generic message on any failure
25→ */
26→export async function wrapKey(
27→  key: Uint8Array,
28→  recipientPublicKey: Uint8Array
29→): Promise<Uint8Array> {
30→  // Validate public key size (uncompressed secp256k1)
31→  if (recipientPublicKey.length !== SECP256K1_PUBLIC_KEY_SIZE) {
32→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_SIZE');
33→  }
34→
35→  // Validate uncompressed public key prefix (0x04)
36→  if (recipientPublicKey[0] !== 0x04) {
37→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_FORMAT');
38→  }
39→
40→  // Validate that the public key is a valid point on secp256k1 curve
41→  try {
42→    ProjectivePoint.fromHex(recipientPublicKey);
43→  } catch {
44→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_FORMAT');
45→  }
46→
47→  try {
48→    // eciesjs encrypt handles:
49→    // 1. Generate ephemeral keypair
50→    // 2. ECDH key agreement
51→    // 3. HKDF key derivation
52→    // 4. AES-GCM encryption
53→    // 5. Return: ephemeral_pubkey || ciphertext || tag
54→    const wrapped = encrypt(recipientPublicKey, key);
55→    return wrapped;
56→  } catch {
57→    // Generic error to prevent information leakage
58→    throw new CryptoError('Key wrapping failed', 'KEY_WRAPPING_FAILED');
59→  }
60→}
61→

  1→/**
  2→ * Shared key-wrapping utilities for ECIES re-wrapping operations.
  3→ *
  4→ * Extracted from ShareDialog to be shared between direct sharing (Phase 14)
  5→ * and invite link sharing (Phase 15). Both flows need to traverse folder
  6→ * metadata and re-wrap descendant keys for a target public key.
  7→ *
  8→ * Security: All plaintext key material is zeroed after use via .fill(0)
  9→ * in finally blocks.
 10→ */
 11→
 12→import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/core';
 13→import { decryptFolderMetadata } from '@cipherbox/core';
 14→import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 15→import { resolveFileMetadata } from '../../services/file-metadata.service';
 16→import { resolveIpnsRecord } from '../../services/ipns.service';
 17→import { fetchFromIpfs } from '../api/ipfs';
 18→import type { ChildKeyDto } from '@cipherbox/api-client';
 19→
 20→/**
 21→ * Collect all descendant keys from a folder for sharing.
 22→ * Traverses subfolders depth-first, re-wrapping each file and subfolder key
 23→ * for the target public key.
 24→ *
 25→ * Works for both direct share (recipientPubKey) and invite link (ephemeralPubKey)
 26→ * since the target key is parameterized.
 27→ *
 28→ * @param children - Children of the current folder
 29→ * @param folderKey - Decrypted AES key of the current folder (for resolving file metadata)
 30→ * @param ownerPrivateKey - Owner's secp256k1 private key for unwrapping ECIES keys
 31→ * @param targetPubKeyBytes - Target uncompressed secp256k1 public key (recipient or ephemeral)
 32→ * @param onProgress - Callback for progress tracking
 33→ */
 34→export async function collectChildKeys(
 35→  children: FolderChild[],
 36→  folderKey: Uint8Array,
 37→  ownerPrivateKey: Uint8Array,
 38→  targetPubKeyBytes: Uint8Array,
 39→  onProgress: (wrapped: number) => void
 40→): Promise<ChildKeyDto[]> {
 41→  const childKeys: ChildKeyDto[] = [];
 42→  let wrapped = 0;
 43→
 44→  for (const child of children) {
 45→    if (child.type === 'file') {
 46→      const fp = child as FilePointer;
 47→      // Resolve file metadata to get fileKeyEncrypted, then re-wrap for target
 48→      try {
 49→        const { metadata: fileMeta } = await resolveFileMetadata(fp.fileMetaIpnsName, folderKey);
 50→        const reWrappedFileKey = await reWrapEncryptedKey(
 51→          fileMeta.fileKeyEncrypted,
 52→          ownerPrivateKey,
 53→          targetPubKeyBytes
 54→        );
 55→        childKeys.push({
 56→          keyType: 'file' as ChildKeyDto['keyType'],
 57→          itemId: fp.id,
 58→          encryptedKey: reWrappedFileKey,
 59→        });
 60→        wrapped++;
 61→        onProgress(wrapped);
 62→      } catch (err) {
 63→        console.error(`Failed to re-wrap file key for ${fp.name}:`, err);
 64→        // Continue with other children
 65→      }
 66→    } else {
 67→      const folder = child as FolderEntry;
 68→      // Re-wrap the subfolder's folderKey for the target
 69→      try {
 70→        const folderKeyRewrapped = await reWrapEncryptedKey(
 71→          folder.folderKeyEncrypted,
 72→          ownerPrivateKey,
 73→          targetPubKeyBytes
 74→        );
 75→        childKeys.push({
 76→          keyType: 'folder' as ChildKeyDto['keyType'],
 77→          itemId: folder.id,
 78→          encryptedKey: folderKeyRewrapped,
 79→        });
 80→        wrapped++;
 81→        onProgress(wrapped);
 82→
 83→        // Recurse into subfolder: resolve its metadata and collect its children
 84→        const resolved = await resolveIpnsRecord(folder.ipnsName);
 85→        if (resolved) {
 86→          const folderKeyBytes = await unwrapKey(
 87→            hexToBytes(folder.folderKeyEncrypted),
 88→            ownerPrivateKey
 89→          );
 90→          try {
 91→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
 92→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
 93→            const encrypted = JSON.parse(encryptedJson);
 94→            const metadata = await decryptFolderMetadata(encrypted, folderKeyBytes);
 95→
 96→            const subKeys = await collectChildKeys(
 97→              metadata.children,
 98→              folderKeyBytes,
 99→              ownerPrivateKey,
100→              targetPubKeyBytes,
101→              (subWrapped) => {
102→                onProgress(wrapped + subWrapped);
103→              }
104→            );
105→            wrapped += subKeys.length;
106→            childKeys.push(...subKeys);
107→          } finally {
108→            folderKeyBytes.fill(0);
109→          }
110→        }
111→      } catch (err) {
112→        console.error(`Failed to re-wrap folder key for ${folder.name}:`, err);
113→        // Continue with other children
114→      }
115→    }
116→  }
117→
118→  return childKeys;
119→}
120→
121→/**
122→ * Re-wrap an ECIES-encrypted hex key from owner to target.
123→ *
124→ * Unwraps with ownerPrivateKey, then wraps for targetPubKey.
125→ * Plaintext key is zeroed after use.
126→ */
127→export async function reWrapEncryptedKey(
128→  encryptedKeyHex: string,
129→  ownerPrivateKey: Uint8Array,
130→  targetPubKey: Uint8Array
131→): Promise<string> {
132→  const plainKey = await unwrapKey(hexToBytes(encryptedKeyHex), ownerPrivateKey);
133→  try {
134→    const rewrapped = await wrapKey(plainKey, targetPubKey);
135→    return bytesToHex(rewrapped);
136→  } finally {
137→    plainKey.fill(0);
138→  }
139→}
